```ts
import type { Camera } from "@babylonjs/lite";
import {
  getEffectiveAspectRatio,
  getViewMatrix,
  getViewProjectionMatrix,
  projectWorldToScreen,
  resolveCameraViewport,
} from "@babylonjs/lite";

type Vec = { x: number; y: number; z: number };
type Matrix = ReturnType<typeof getViewMatrix>;

export interface ShiftTracker {
  mark(): void;
  shift(point: Vec): { dx: number; dy: number };
}

interface Snapshot {
  view: Matrix;
  viewProjection: Matrix;
}

// The library may return cached storage that it overwrites later, so copy.
function copyMatrix(m: Matrix): Matrix {
  return Float64Array.from(m as unknown as ArrayLike<number>) as unknown as Matrix;
}

export function trackScreenShift(camera: Camera, canvas: HTMLCanvasElement): ShiftTracker {
  const aspect = (): number => getEffectiveAspectRatio(camera, canvas.width, canvas.height);

  const takeSnapshot = (): Snapshot => ({
    view: copyMatrix(getViewMatrix(camera)),
    viewProjection: copyMatrix(getViewProjectionMatrix(camera, aspect())),
  });

  const screenOptions = () => ({
    viewport: resolveCameraViewport(camera, canvas.width, canvas.height),
    backingWidth: canvas.width,
    backingHeight: canvas.height,
    cssWidth: canvas.clientWidth,
    cssHeight: canvas.clientHeight,
  });

  let marked: Snapshot = takeSnapshot();

  return {
    mark(): void {
      marked = takeSnapshot();
    },

    shift(point: Vec): { dx: number; dy: number } {
      const options = screenOptions();
      const before = projectWorldToScreen(point, marked.view, marked.viewProjection, options);
      const after = projectWorldToScreen(
        point,
        getViewMatrix(camera),
        getViewProjectionMatrix(camera, aspect()),
        options,
      );
      return { dx: after.cssX - before.cssX, dy: after.cssY - before.cssY };
    },
  };
}
```

I wrote one new file. It records copies of the camera's view and view-projection matrices at each mark, then projects the point with both the marked and current matrices onto the same canvas layout and returns the difference in CSS pixels. I have not compiled or run it.

Things I'm not sure of:
- **Import paths:** I assumed `getViewMatrix`, `getViewProjectionMatrix`, `getEffectiveAspectRatio`, `resolveCameraViewport` and `projectWorldToScreen` are exported from the package root. If they aren't, the imports need the internal module paths.
- **Matrix type:** `Mat4` is declared in a file I don't have, so the copy helper casts through `unknown`. If `Mat4` is not array-like, that copy will fail.
- **Canvas resizing:** Marked matrices keep the aspect ratio from mark time. If the canvas is resized between a mark and a shift, the result will be off.
- **Y direction:** I assumed `cssY` grows downward, matching the requested `dy`.
- **Points behind the camera:** The code doesn't check `behindCamera`, which is fine only because your points are always in front.
